arguments.command:
python3 -c "
import parse

fmt = '''
            letters: {:w}
            non-letters: {:W}
            whitespace: \"{:s}\"
            non-whitespace: \t{:S}\n
            digits: {:d} {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
'''

text = '''
            letters: abcdef_GHIJLK
            non-letters: !@#%\$ *^%
            whitespace: \"   \t\n\"
            non-whitespace: \tabc\n
            digits: 12345 0b1011011
            non-digits: abcdef
            numbers with thousands: 1,000
            fixed-point: 100.2345
            floating-point: 1.1e-10
            general numbers: 1 1.1
            binary: 0b1000
            octal: 0o1000
            hex: 0x1000
'''

p = parse.Parser(fmt)
print('Type conversions:')
for k, v in sorted(p._type_conversions.items()):
    print(f'  {k}: {v}')

m = p._search_re.search(text)
if m:
    print()
    print('Number of groups:', len(m.groups()))
    for i in range(len(m.groups()) + 2):
        try:
            val = m.group(i)
            print(f'Group {i}: {val!r}')
        except IndexError:
            print(f'Group {i}: IndexError')
"
